def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("Input must be between 1 and 3999 inclusive")

    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, numeral in roman_numerals:
        while n >= value:
            result.append(numeral)
            n -= value
    return ''.join(result)


def from_roman(s):
    """Convert a Roman numeral string back to an integer."""
    if not isinstance(s, str) or not s:
        raise ValueError("Input must be a non-empty string")

    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    # Validate that all characters are valid Roman numeral characters
    for ch in s:
        if ch not in roman_values:
            raise ValueError(f"Invalid character in Roman numeral: {ch}")

    # Convert to list of values
    values = [roman_values[ch] for ch in s]

    # Check for invalid subtractive patterns
    # A smaller value before a larger one means subtraction, but only certain pairs are allowed
    allowed_subtractive = {
        ('I', 'V'): True, ('I', 'X'): True, ('I', 'M'): True,
        ('X', 'L'): True, ('X', 'C'): True, ('X', 'D'): True,
        ('X', 'M'): True,
        ('C', 'D'): True, ('C', 'M'): True,
    }

    for i in range(len(values) - 1):
        if values[i] < values[i + 1]:
            pair = (s[i], s[i + 1])
            if pair not in allowed_subtractive:
                raise ValueError(f"Invalid subtractive pattern: {pair}")

    # Calculate the value
    total = 0
    for i in range(len(values)):
        if i < len(values) - 1 and values[i] < values[i + 1]:
            total += values[i + 1] - values[i]
            i += 1  # skip next
        else:
            total += values[i]

    # Re-validate by converting back
    if to_roman(total) != s:
        raise ValueError("Roman numeral is not well-formed")

    return total

import pytest
from roman import to_roman, from_roman


# ── to_roman basic cases ──────────────────────────────────────────────

class TestToRomanBasic:
    def test_one(self):
        assert to_roman(1) == 'I'

    def test_two(self):
        assert to_roman(2) == 'II'

    def test_three(self):
        assert to_roman(3) == 'III'

    def test_four(self):
        assert to_roman(4) == 'IV'

    def test_five(self):
        assert to_roman(5) == 'V'

    def test_nine(self):
        assert to_roman(9) == 'IX'

    def test_ten(self):
        assert to_roman(10) == 'X'

    def test_forty(self):
        assert to_roman(40) == 'XL'

    def test_fifty(self):
        assert to_roman(50) == 'L'

    def test_ninety(self):
        assert to_roman(90) == 'XC'

    def test_hundred(self):
        assert to_roman(100) == 'C'

    def test_four_hundred(self):
        assert to_roman(400) == 'CD'

    def test_five_hundred(self):
        assert to_roman(500) == 'D'

    def test_nine_hundred(self):
        assert to_roman(900) == 'CM'

    def test_thousand(self):
        assert to_roman(1000) == 'M'

    def test_three_thousand(self):
        assert to_roman(3000) == 'MMM'

    def test_max(self):
        assert to_roman(3999) == 'MMMCMXCIX'

    def test_random_mid(self):
        assert to_roman(42) == 'XLII'
        assert to_roman(1994) == 'MCMXCIV'
        assert to_roman(2023) == 'MMXXIII'


# ── to_roman boundary / error cases ───────────────────────────────────

class TestToRomanErrors:
    def test_zero(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative(self):
        with pytest.raises(ValueError):
            to_roman(-1)

    def test_too_large(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    def test_float(self):
        with pytest.raises(ValueError):
            to_roman(3.14)

    def test_string(self):
        with pytest.raises(ValueError):
            to_roman("X")

    def test_bool(self):
        with pytest.raises(ValueError):
            to_roman(True)

    def test_none(self):
        with pytest.raises(ValueError):
            to_roman(None)

    def test_list(self):
        with pytest.raises(ValueError):
            to_roman([1])


# ── from_roman valid numerals ─────────────────────────────────────────

class TestFromRomanValid:
    def test_i(self):
        assert from_roman('I') == 1

    def test_v(self):
        assert from_roman('V') == 5

    def test_x(self):
        assert from_roman('X') == 10

    def test_l(self):
        assert from_roman('L') == 50

    def test_c(self):
        assert from_roman('C') == 100

    def test_d(self):
        assert from_roman('D') == 500

    def test_m(self):
        assert from_roman('M') == 1000

    def test_iv(self):
        assert from_roman('IV') == 4

    def test_ix(self):
        assert from_roman('IX') == 9

    def test_xl(self):
        assert from_roman('XL') == 40

    def test_xc(self):
        assert from_roman('XC') == 90

    def test_cd(self):
        assert from_roman('CD') == 400

    def test_cm(self):
        assert from_roman('CM') == 900

    def test_mcmxciv(self):
        assert from_roman('MCMXCIV') == 1994

    def test_mmmcmxcix(self):
        assert from_roman('MMMCMXCIX') == 3999

    def test_uppercase_only(self):
        assert from_roman('MMMCMXCIX') == 3999

    def test_lowercase_rejected(self):
        with pytest.raises(ValueError):
            from_roman('iii')


# ── from_roman invalid numerals ───────────────────────────────────────

class TestFromRomanInvalid:
    def test_empty(self):
        with pytest.raises(ValueError):
            from_roman('')

    def test_spaces(self):
        with pytest.raises(ValueError):
            from_roman(' I ')

    def test_iiii(self):
        with pytest.raises(ValueError):
            from_roman('IIII')

    def test_vv(self):
        with pytest.raises(ValueError):
            from_roman('VV')

    def test_ic(self):
        with pytest.raises(ValueError):
            from_roman('IC')

    def test_xm(self):
        with pytest.raises(ValueError):
            from_roman('XM')

    def test_mmmm(self):
        with pytest.raises(ValueError):
            from_roman('MMMM')

    def test_banana(self):
        with pytest.raises(ValueError):
            from_roman('banana')

    def test_il(self):
        with pytest.raises(ValueError):
            from_roman('IL')

    def test_im(self):
        with pytest.raises(ValueError):
            from_roman('IM')

    def test_xlil(self):
        with pytest.raises(ValueError):
            from_roman('XLIL')

    def test_non_ascii(self):
        with pytest.raises(ValueError):
            from_roman('Ⅰ')

    def test_none_input(self):
        with pytest.raises(ValueError):
            from_roman(None)

    def test_int_input(self):
        with pytest.raises(ValueError):
            from_roman(42)

    def test_mixed_case(self):
        with pytest.raises(ValueError):
            from_roman('Ii')

    def test_duplicate_subtractive(self):
        """e.g. IIV is not valid (two I's before V)"""
        with pytest.raises(ValueError):
            from_roman('IIV')

    def test_double_v_before_x(self):
        with pytest.raises(ValueError):
            from_roman('VVX')


# ── round-trip property ───────────────────────────────────────────────

class TestRoundTrip:
    def test_all_ranges(self):
        for n in range(1, 4000):
            assert from_roman(to_roman(n)) == n

